async function sb(path,opts={},token){if(!SB_URL||!SB_KEY)throw new Error('AIRDROP PUBGM backend is not connected yet. Add your new Supabase URL and publishable key in Vercel.');const headers={apikey:SB_KEY,'Content-Type':'application/json',...(opts.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(`${SB_URL}${path}`,{...opts,headers});const text=await r.text();let data;try{data=text?JSON.parse(text):null}catch{data=text}if(!r.ok)throw new Error(data?.message||data?.msg||data?.error_description||data?.hint||text||`Request failed (${r.status})`);return data}
async function rpc(name,args,token){return sb(`/rest/v1/rpc/${name}`,{method:'POST',body:JSON.stringify(args)},token)}
function saveSession(s){if(s)localStorage.setItem('airdrop_session',JSON.stringify(s));else localStorage.removeItem('airdrop_session')}
function loadSession(){try{return JSON.parse(localStorage.getItem('airdrop_session')||'null')}catch{return null}}
function userId(token){try{return JSON.parse(atob(token.split('.')[1])).sub}catch{return ''}}
function avatarUrl(path){return path?`${SB_URL}/storage/v1/object/public/avatars/${path}`:''}
function displayStatus(a){const t=new Date(a.scheduled_start).getTime(),end=t+(a.duration_minutes||60)*60000,now=Date.now();if(a.status==='cancelled')return 'cancelled';if(a.status==='completed')return 'completed';if(now>=end)return 'completed';if(now>=t)return 'live';if(now>=t-15*60000)return 'check_in';return 'upcoming'}

