function Tournaments({go}){const token=loadSession()?.access_token;const [items,setItems]=useState([]),[selected,setSelected]=useState(null),[matches,setMatches]=useState([]),[stages,setStages]=useState([]),[players,setPlayers]=useState({}),[files,setFiles]=useState({}),[notes,setNotes]=useState({}),[busy,setBusy]=useState(true),[sending,setSending]=useState({}),[msg,setMsg]=useState('');useEffect(()=>{if(!token)return;sb('/rest/v1/activities?select=*&type=eq.tournament&order=scheduled_start.asc&limit=50',{},token).then(setItems).catch(e=>setMsg(e.message)).finally(()=>setBusy(false))},[token]);async function open(a){setSelected(a);setMsg('');try{const ss=await sb('/rest/v1/tournament_stages?select=*&activity_id=eq.'+a.id+'&order=stage_number.asc',{},token);setStages(ss||[]);if(ss?.length){const ids=ss.map(x=>x.id).join(',');const mm=await sb('/rest/v1/tournament_matches?select=*&stage_id=in.('+ids+')&order=round_number.asc,match_number.asc',{},token)||[];setMatches(mm);const pids=[...new Set(mm.flatMap(m=>[m.player_a,m.player_b,m.winner_id].filter(Boolean)))];if(pids.length){const pp=await sb('/rest/v1/public_profiles?select=id,profile_name,username&id=in.('+pids.join(',')+')',{},token);setPlayers(Object.fromEntries((pp||[]).map(p=>[p.id,p])))}else setPlayers({})}else{setMatches([]);setPlayers({})}}catch(e){setMsg(e.message)}}function playerLabel(id){if(!id)return 'TBD';const p=players[id];return p?(p.username?'@'+p.username:p.profile_name||'AIRDROP player'):'Player'}async function seed(){if(!selected)return;try{await rpc('seed_tournament',{p_activity_id:selected.id},token);await open(selected);setMsg('Bracket seeded.')}catch(e){setMsg(e.message)}}async function result(m,w){const file=files[m.id];if(!file){setMsg('Choose a screenshot or match video first.');return}const allowed=['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime'];if(!allowed.includes(file.type)){setMsg('Use JPG, PNG, WEBP, GIF, MP4, WEBM or MOV.');return}if(file.size>100*1024*1024){setMsg('Evidence file must be 100 MB or smaller.');return}setSending(x=>({...x,[m.id]:true}));setMsg('');try{const uid=userId(token),ext=(file.name.split('.').pop()||'bin').toLowerCase().replace(/[^a-z0-9]/g,'');const path=uid+'/'+m.id+'/'+crypto.randomUUID()+'.'+ext;await sb('/storage/v1/object/tournament-evidence/'+path,{method:'POST',headers:{'Content-Type':file.type,'x-upsert':'false'},body:file},token);await rpc('report_tournament_result',{p_match_id:m.id,p_winner_id:w,p_evidence_url:path,p_notes:notes[m.id]||null},token);setFiles(x=>({...x,[m.id]:null}));setNotes(x=>({...x,[m.id]:''}));await open(selected);setMsg('Evidence uploaded. Result submitted for admin review; the bracket will advance only after approval.')}catch(e){setMsg(e.message||'Could not submit tournament evidence.')}finally{setSending(x=>({...x,[m.id]:false}))}}return <main className="page"><div className="card"><div className="sectionhead"><div><h1>Tournaments</h1><span>Live bracket workflow</span></div><button className="btn small" onClick={()=>go('home')}>Home</button></div>{busy?<p className="muted">Loading tournaments…</p>:items.length?items.map(a=><button className="card" key={a.id} onClick={()=>open(a)}><b>{a.title}</b><small>{a.status} · {a.capacity} players · {a.game_mode||'PUBG MOBILE'}</small></button>):<p className="muted">No tournaments yet.</p>}{selected&&<div className="section"><h2>{selected.title}</h2>{!stages.length?<><p className="muted">No bracket has been generated.</p><button className="btn primary" onClick={seed}>Seed bracket</button></>:stages.map(st=><details className="card tournament-stage" key={st.id} open={st.stage_number===1}><summary><b>{st.name}</b><span>{matches.filter(m=>m.stage_id===st.id).length} matches</span></summary>{matches.filter(m=>m.stage_id===st.id).map(m=><div className="row" key={m.id}><div><b>{playerLabel(m.player_a)} vs {playerLabel(m.player_b)}</b><span>{m.status==='completed'?'Winner: '+playerLabel(m.winner_id):m.status}</span></div>{m.status==='pending'&&m.player_a&&m.player_b&&selected.creator_id===userId(token)&&<div className="section"><label className="field"><span>Match screenshot or video (max 100 MB)</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime" onChange={e=>setFiles(x=>({...x,[m.id]:e.target.files?.[0]||null}))}/></label><label className="field"><span>Note for admin (optional)</span><input value={notes[m.id]||''} maxLength={1000} onChange={e=>setNotes(x=>({...x,[m.id]:e.target.value}))} placeholder="Brief match details"/></label><span>{files[m.id]?.name||'No evidence selected'}</span><div className="row"><button className="btn small" disabled={!!sending[m.id]||!files[m.id]} onClick={()=>result(m,m.player_a)}>{sending[m.id]?'Uploading…':playerLabel(m.player_a)+' wins'}</button><button className="btn small" disabled={!!sending[m.id]||!files[m.id]} onClick={()=>result(m,m.player_b)}>{playerLabel(m.player_b)+' wins'}</button></div></div>}</div>)}</details>)}{msg&&<p className="warning">{msg}</p>}</div>}</div></main>}
function Achievements({go}){const token=loadSession()?.access_token;const [items,setItems]=useState([]),[defs,setDefs]=useState([]),[msg,setMsg]=useState('');useEffect(()=>{if(!token)return;(async()=>{try{const [a,u]=await Promise.all([sb('/rest/v1/achievements?select=*&order=requirement_value.asc',{},token),sb('/rest/v1/user_achievements?select=achievement_id,unlocked_at',{},token)]);const map=new Map((u||[]).map(x=>[x.achievement_id,x]));setDefs(a||[]);setItems((a||[]).map(x=>({...x,unlocked:map.has(x.id),unlocked_at:map.get(x.id)?.unlocked_at})))}catch(e){setMsg(e.message)}})()},[token]);async function refresh(){try{await rpc('refresh_user_achievements', {p_user_id:userId(token)},token);const u=await sb('/rest/v1/user_achievements?select=achievement_id,unlocked_at',{},token);const map=new Map((u||[]).map(x=>[x.achievement_id,x]));setItems(defs.map(x=>({...x,unlocked:map.has(x.id),unlocked_at:map.get(x.id)?.unlocked_at})));setMsg('Progress refreshed.')}catch(e){setMsg(e.message)}}return <main className="page"><div className="card"><div className="sectionhead"><div><h1>Achievements</h1><span>{items.filter(x=>x.unlocked).length}/{items.length} unlocked</span></div><button className="btn small" onClick={()=>go('home')}>Home</button></div><button className="btn primary" onClick={refresh}>Refresh progress</button>{items.map(x=><div className="row" key={x.id}><div><b>{x.name}</b><span>{x.description} · {x.requirement_type} {x.requirement_value}</span></div><strong>{x.unlocked?'✓':'—'}</strong></div>)}{msg&&<p className="warning">{msg}</p>}</div></main>}

